import{_ as p,a0 as o,w as r,s as u,I as e,x as n,a1 as a,A as i,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Ubuntu 16.04 和 Fedora 22-24 上安装最新的 XFCE 桌面？ | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 16.04 和 Fedora 22-24 上安装最新的 XFCE 桌面？ | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 16.04 和 Fedora 22-24 上安装最新的 XFCE 桌面？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 16.04 和 Fedora 22-24 上安装最新的 XFCE 桌面？ | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160917 How to Install Latest XFCE Desktop in Ubuntu 16.04 and Fedora 22-24","title":"如何在 Ubuntu 16.04 和 Fedora 22-24 上安装最新的 XFCE 桌面？","tag":"201609","desc":""},"relativePath":"201609/20160917 How to Install Latest XFCE Desktop in Ubuntu 16.04 and Fedora 22-24.md","filePath":"[post].md"}'),d={name:"201609/20160917 How to Install Latest XFCE Desktop in Ubuntu 16.04 and Fedora 22-24.md"};function f(m,t,b,k,g,x){const s=o("Link");return r(),u("div",null,[t[22]||(t[22]=e("h1",{id:"如何在-ubuntu-16-04-和-fedora-22-24-上安装最新的-xfce-桌面",tabindex:"-1"},[n("如何在 Ubuntu 16.04 和 Fedora 22-24 上安装最新的 XFCE 桌面？ "),e("a",{class:"header-anchor",href:"#如何在-ubuntu-16-04-和-fedora-22-24-上安装最新的-xfce-桌面","aria-label":"Permalink to “如何在 Ubuntu 16.04 和 Fedora 22-24 上安装最新的 XFCE 桌面？”"},"​")],-1)),e("p",null,[t[1]||(t[1]=n("Xfce 是一款针对 Linux 系统的现代化",-1)),a(s,{href:"http://www.tecmint.com/best-linux-desktop-environments/"},{default:i(()=>[...t[0]||(t[0]=[n("轻型开源桌面环境",-1)])]),_:1}),t[2]||(t[2]=n("，它在其他的类 Unix 系统上，比如 Mac OS X、 Solaries、 *BSD 以及其它几种上也能工作得很好。它非常快并以简洁而优雅的用户界面展现了用户友好性。",-1))]),t[23]||(t[23]=l('<p>在服务器上安装一个桌面环境有时还是有用的，因为某些应用程序可能需要一个桌面界面，以便高效而可靠的管理。 Xfce 的一个卓越的特性是其内存消耗等系统资源占用率很低，因此，如果服务器需要一个桌面环境的话它会是首选。</p><h3 id="xfce-桌面的功能特性" tabindex="-1">XFCE 桌面的功能特性 <a class="header-anchor" href="#xfce-桌面的功能特性" aria-label="Permalink to “XFCE 桌面的功能特性”">​</a></h3><p>另外，它的一些值得注意的组件和功能特性列在下面：</p><ul><li>Xfwm 窗口管理器</li><li>Thunar 文件管理器</li><li>用户会话管理器：用来处理用户登录、电源管理之类</li><li>桌面管理器：用来设置背景图片、桌面图标等等</li><li>应用管理器</li><li>它的高度可连接性以及一些其他次要功能特性</li></ul>',4)),e("p",null,[t[4]||(t[4]=n("Xfce 的最新稳定发行版是 Xfce 4.12，它所有的功能特性和与旧版本的变化都列在了",-1)),a(s,{href:"https://www.xfce.org/about/news/?post=1425081600"},{default:i(()=>[...t[3]||(t[3]=[n("这儿",-1)])]),_:1}),t[5]||(t[5]=n("。",-1))]),t[24]||(t[24]=l(`<h4 id="在-ubuntu-16-04-上安装-xfce-桌面" tabindex="-1">在 Ubuntu 16.04 上安装 Xfce 桌面 <a class="header-anchor" href="#在-ubuntu-16-04-上安装-xfce-桌面" aria-label="Permalink to “在 Ubuntu 16.04 上安装 Xfce 桌面”">​</a></h4><p>Linux 发行版，比如 Xubuntu、Manjaro、OpenSUSE、Fedora Xfce Spin、Zenwalk 以及许多其他发行版都提供它们自己的 Xfce 桌面安装包，但你也可以像下面这样安装最新的版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install xfce4</span></span></code></pre></div><p>等待安装过程结束，然后退出当前会话，或者你也可以选择重启系统。在登录界面，选择 Xfce 桌面，然后登录，截图如下：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/09/Select-Xfce-Desktop-at-Login.png" alt=""></p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/09/XFCE-Desktop.png" alt=""></p><h4 id="在-fedora-22-24-上安装-xfce-桌面" tabindex="-1">在 Fedora 22-24 上安装 Xfce 桌面 <a class="header-anchor" href="#在-fedora-22-24-上安装-xfce-桌面" aria-label="Permalink to “在 Fedora 22-24 上安装 Xfce 桌面”">​</a></h4><p>如果你已经有一个安装好的 Linux 发行版 Fedora，想在上面安装 xfce 桌面，那么你可以使用如下所示的 yum 或 dnf 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-------------------- 在 Fedora 22 上 --------------------</span></span>
<span class="line"><span># yum install @xfce</span></span>
<span class="line"><span>-------------------- 在 Fedora 23-24 上 --------------------</span></span>
<span class="line"><span># dnf install @xfce-desktop-environment</span></span></code></pre></div><p>安装 Xfce 以后，你可以从会话菜单选择 Xfce 登录或者重启系统。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/09/Select-Xfce-Desktop-at-Fedora-Login.png" alt=""></p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/09/Install-Xfce-Desktop-in-Fedora.png" alt=""></p><p>如果你不再想要 Xfce 桌面留在你的系统上，那么可以使用下面的命令来卸载它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-------------------- 在 Ubuntu 16.04 上 -------------------- </span></span>
<span class="line"><span>$ sudo apt purge xfce4</span></span>
<span class="line"><span>$ sudo apt autoremove</span></span>
<span class="line"><span>-------------------- 在 Fedora 22 上 -------------------- </span></span>
<span class="line"><span># yum remove @xfce</span></span>
<span class="line"><span>-------------------- 在 Fedora 23-24 上 --------------------</span></span>
<span class="line"><span># dnf remove @xfce-desktop-environment</span></span></code></pre></div>`,14)),e("p",null,[t[7]||(t[7]=n("在这个简单的入门指南中，我们讲解了如何安装最新版 Xfce 桌面的步骤，我相信这很容易掌握。如果一切进行良好，你可以享受一下使用 xfce —— 这个",-1)),a(s,{href:"http://www.tecmint.com/best-linux-desktop-environments/"},{default:i(()=>[...t[6]||(t[6]=[n(" Linux 系统上最佳桌面环境",-1)])]),_:1}),t[8]||(t[8]=n("之一。",-1))]),t[25]||(t[25]=e("p",null,"此外，如果你再次回来，你可以通过下面的反馈表单和我们始终保持联系。",-1)),t[26]||(t[26]=e("hr",null,null,-1)),e("p",null,[t[10]||(t[10]=n("via: ",-1)),a(s,{href:"http://www.tecmint.com/install-xfce-desktop-in-ubuntu-fedora/"},{default:i(()=>[...t[9]||(t[9]=[n("http://www.tecmint.com/install-xfce-desktop-in-ubuntu-fedora/",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=n("作者：",-1)),a(s,{href:"http://www.tecmint.com/author/aaronkili/"},{default:i(()=>[...t[11]||(t[11]=[n("Aaron Kili",-1)])]),_:1}),t[15]||(t[15]=n(" 译者：",-1)),a(s,{href:"https://github.com/ucasFL"},{default:i(()=>[...t[12]||(t[12]=[n("ucasFL",-1)])]),_:1}),t[16]||(t[16]=n(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:i(()=>[...t[13]||(t[13]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[19]||(t[19]=n("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[17]||(t[17]=[n("LCTT",-1)])]),_:1}),t[20]||(t[20]=n(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:i(()=>[...t[18]||(t[18]=[n("Linux中国",-1)])]),_:1}),t[21]||(t[21]=n(" 荣誉推出",-1))])])}const F=p(d,[["render",f]]);export{C as __pageData,F as default};
